ee:variables.ee:set-variable:
%dw 2.0 var currentDate = now() as String { format: "yyyy-MM-dd" } output application/json
--- { case_id : payload.caseID, source: payload.source, case_type: payload.caseType, first_name: payload.firstName, last_name: payload.lastName, phone: payload.phone, email: payload.email, date_of_birth: payload.dateOfBirth as String { format: "yyyy-MM-dd" }, national_id: payload.nationalID, national_id_type: payload.nationalIDType, street_address: payload.address.streetAddress, city: payload.address.city, state: upper(payload.address.state), postal: payload.address.postal, country: payload.address.country, update_date: currentDate, create_by: "UHIS", update_by: "UHIS"
}
